export function requestCommit<Row, A>(read: () => Row, persist: (row: Row) => A, conflict: (error: unknown) => boolean): A {
  const attempt = commit(Effect.try({ try: read, catch: (error) => error }), (row) => Effect.try({ try: () => persist(row), catch: (error) => error }), conflict)
  const result = Effect.runSync(Effect.result(attempt))
  if (result._tag === 'Failure') throw result.failure
  return result.success
}

