})

export function integrationConfig(harness: string, entry = serverEntry()): string {
  const json = (value: unknown) => JSON.stringify(value, null, 2)
  switch (harness) {
    case 'claude-code':
    case 'codex':
    case 'cursor':
      return json({ mcpServers: { civic: entry } })
